CREATE POLICY "client team can update interviews" ON public.interviews FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM applications a JOIN positions p ON p.id = a.position_id WHERE a.id = interviews.application_id AND public.is_client_team_member(p.client_id, auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM applications a JOIN positions p ON p.id = a.position_id WHERE a.id = interviews.application_id AND public.is_client_team_member(p.client_id, auth.uid())));